WITH m AS (SELECT CASE WHEN days_past_due=0 THEN 0 WHEN days_past_due<30 THEN 1 WHEN days_past_due<60 THEN 2 WHEN days_past_due<90 THEN 3 ELSE 4 END AS b, LEAD(CASE WHEN days_past_due=0 THEN 0 WHEN days_past_due<30 THEN 1 WHEN days_past_due<60 THEN 2 WHEN days_past_due<90 THEN 3 ELSE 4 END) OVER (PARTITION BY loan_id ORDER BY snapshot_date) AS bn, snapshot_date, loan_status, LEAD(snapshot_date) OVER (PARTITION BY loan_id ORDER BY snapshot_date) AS dn FROM loan_monthly_snapshot),
t AS (SELECT b, bn, COUNT(*) AS n FROM m WHERE snapshot_date>=DATE '2025-01-31' AND snapshot_date<DATE '2025-12-31' AND loan_status<>'Closed' AND dn=last_day(snapshot_date + INTERVAL 1 MONTH) GROUP BY 1,2)
SELECT b, bn, n, ROUND(100.0*n/SUM(n) OVER (PARTITION BY b),1) FROM t ORDER BY 1,2
